231.sql:
SELECT 
    (SELECT bond_type FROM bond WHERE molecule_id = 'TR010' GROUP BY bond_type ORDER BY COUNT(*) DESC LIMIT 1) AS majority_bond_type,
    (SELECT label FROM molecule WHERE molecule_id = 'TR010') AS is_carcinogenic;

291.sql:
SELECT COUNT(*) 
FROM molecule 
WHERE label = '+';

303.sql:
SELECT 
    (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS double_bonds,
    (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS carcinogenic;

337.sql:
SELECT `element` FROM atom WHERE `molecule_id` = 'TR002'
UNION ALL
SELECT `bond_type` FROM bond WHERE `molecule_id` = 'TR002';

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

591.sql:
SELECT COUNT(DISTINCT `UserId`) AS answer
FROM badges
WHERE `Name` = 'Supporter' AND STRFTIME('%Y', `Date`) = '2011';

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE `Location` = 'New York';

653.sql:
SELECT OwnerDisplayName
FROM posts
WHERE ViewCount = (SELECT MAX(ViewCount) FROM posts);

937.sql:
SELECT `time` 
FROM results 
WHERE raceId = 34 AND position = 2;

1393.sql:
SELECT first_name, last_name, email 
FROM member 
WHERE position = 'Secretary';
